/* Determine whether the call now being made is the one the test asked to fail.
   Only calls made while accounting is active are considered, which keeps the
   objects created by tx_freertos_init() and by the harness out of the count.  */
static int txfr_should_fail(TXFR_INJECT_TARGET target)
{
    if((txfr_accounting == 0) || (txfr_inject_target != target))
    {
        return 0;
    }

    txfr_inject_call_index++;

    return (txfr_inject_call_index == txfr_inject_fail_on) ? 1 : 0;
}


UINT __wrap__txe_byte_allocate(TX_BYTE_POOL *pool_ptr, VOID **memory_ptr, ULONG memory_size, ULONG wait_option)
{
    if(txfr_accounting != 0)
    {
        txfr_counters.byte_allocate++;
    }

    return __real__txe_byte_allocate(pool_ptr, memory_ptr, memory_size, wait_option);
}


