void txfr_test_account_start(TXFR_INJECT_TARGET target, int fail_on_call)
{
    TX_MEMSET(&txfr_counters, 0, sizeof(txfr_counters));
    txfr_inject_target =     target;
    txfr_inject_fail_on =    fail_on_call;
    txfr_inject_call_index = 0;
    txfr_accounting =        1;
}


void txfr_test_account_stop(TXFR_COUNTERS *p_counters)
{
    txfr_accounting =    0;
    txfr_inject_target = TXFR_INJECT_NONE;

    if(p_counters != NULL)
    {
        *p_counters = txfr_counters;
    }
}


void txfr_test_check(const char *label, int condition)
{
    printf("%-52s %s\n", label, (condition != 0) ? "PASS" : "FAIL");

    if(condition == 0)
    {
        txfr_failures++;
    }
}


void txfr_test_check_counts(const char *label, const TXFR_COUNTERS *p_counters,
                            int expect_allocate, int expect_release,
                            int expect_object_create, int expect_object_delete)
{
    int object_create;
    int object_delete;
    int ok;

    /* Only one kind of kernel object is exercised per check, so the totals
       identify it unambiguously.  */
    object_create = p_counters->semaphore_create + p_counters->mutex_create +
                    p_counters->event_flags_create + p_counters->timer_create +
                    p_counters->thread_create;
    object_delete = p_counters->semaphore_delete + p_counters->mutex_delete +
                    p_counters->event_flags_delete + p_counters->timer_delete +
                    p_counters->thread_delete;

    ok = ((p_counters->byte_allocate == expect_allocate) &&
          (p_counters->byte_release == expect_release) &&
          (object_create == expect_object_create) &&
          (object_delete == expect_object_delete)) ? 1 : 0;

    printf("%-52s %s\n", label, (ok != 0) ? "PASS" : "FAIL");

    if(ok == 0)
    {
        printf("%-52s   got      alloc=%d release=%d create=%d delete=%d\n", "",
               p_counters->byte_allocate, p_counters->byte_release, object_create, object_delete);
        printf("%-52s   expected alloc=%d release=%d create=%d delete=%d\n", "",
               expect_allocate, expect_release, expect_object_create, expect_object_delete);
        txfr_failures++;
    }
}


int txfr_test_failures(void)
{
    return txfr_failures;
}


/* Test thread. The byte pool operations under test require thread context.  */

static TX_THREAD  txfr_test_thread;
static ULONG      txfr_test_stack[4096];


static void txfr_test_thread_entry(ULONG id)
{
    (void)id;

    txfr_test_body();

    printf("\n%s\n", (txfr_failures == 0) ? "ALL CHECKS PASSED" : "THERE WERE FAILED CHECKS");
    fflush(stdout);

    /* The kernel owns the calling thread, so returning here would simply idle.
       Leave the process with a status ctest can read.  */
    exit((txfr_failures == 0) ? 0 : 1);
}


void tx_application_define(void *first_unused_memory)
{
    UINT ret;

    (void)first_unused_memory;

    ret = tx_freertos_init();
    if(ret != TX_SUCCESS)
    {
        printf("tx_freertos_init() failed with %u\n", ret);
        exit(2);
    }

    ret = tx_thread_create(&txfr_test_thread, "txfr_test", txfr_test_thread_entry, 0u,
                           txfr_test_stack, sizeof(txfr_test_stack), 16u, 16u, 0u, TX_AUTO_START);
    if(ret != TX_SUCCESS)
    {
        printf("tx_thread_create() failed with %u\n", ret);
        exit(2);
    }
}


int main(void)
{
    tx_kernel_enter();

    return 0;
}
